use aap::caps::http_client;

/// The node's entire network authority. The host enforces the same allowlist
/// at the boundary; this local check only keeps one out-of-scope URL in an
/// untrusted subscription list from trapping the whole run.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extracts the host of an http(s) URL, or `None` if the URL is malformed.
fn host_of(url: &str) -> Option<&str> {
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let authority = rest.split(['/', '?', '#']).next()?;
    // Drop any userinfo ("user:pass@host"), then any port ("host:443").
    let host = authority.rsplit('@').next()?;
    let host = host.split(':').next()?;
    if host.is_empty() {
        None
    } else {
        Some(host)
    }
}

fn in_scope(url: &str) -> bool {
    match host_of(url) {
        Some(host) => ALLOWED_HOSTS.iter().any(|a| a.eq_ignore_ascii_case(host)),
        None => false,
    }
}

