    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            if !in_scope(&url) {
                failures.push(FetchFailure {
                    url,
                    error: "url host is outside this node's fetch scope".into(),
                });
                continue;
            }

            // Transport failures (timeout, error status, oversize body) come
            // back as Err and are recorded, so one dead feed does not fail the run.
            // An out-of-allowlist request would trap at the boundary, which is
            // why the check above runs first.
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

